#include <string>
#include <sstream>

using namespace std;

class Solution {
public:
    int lengthLongestPath(string input) {
        istringstream ss(input);
        string line;
        vector<int> pathLength(1, 0);
        int maxLen = 0;

        while (getline(ss, line)) {
            int level = line.find_last_of('	') + 1;
            int len = line.size() - level;

            if (line.find('.') != string::npos) {
                maxLen = max(maxLen, pathLength[level] + len);
            } else {
                if (pathLength.size() <= level + 1)
                    pathLength.resize(level + 2);
                pathLength[level + 1] = pathLength[level] + len + 1;
            }
        }

        return maxLen;
    }
};
